import { CompactDataQualityKpi } from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/analysisReliabilityKpi/CompactDataQualityKpi.feature'
import { RELIABILITY_TONES } from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/helpers/presenters/qualityReliabilityPresentation'
import { normalizeCoveragePercentage } from '@/domains/portfolio/features/data-quality/features/assessment/helpers/presenters/normalizeCoveragePercentage'
import type { AnalysisReliabilityTone } from '@/domains/portfolio/features/data-quality/features/assessment/helpers/quality/analysisReliability/analysisReliability.types'
import type { QualityThemeId } from '@/domains/portfolio/features/data-quality/features/assessment/types/dataQuality.type'
import { type FilterScopeSpec } from '@/domains/portfolio/shared/components/filters/FilterScopeBadges.feature'
import i18n from '@/i18n/i18n'
import { useFormatMoney } from '@/shared/helpers/formatters/useFormatMoney'
import { useFormatPercentage } from '@/shared/helpers/formatters/useFormatPercentage'

export function AnalysisReliabilityKpi({
  percentage,
  amount,
  metricLabel,
  tone,
  tooltip,
  qualityTheme,
  scope,
}: {
  percentage: number | null
  amount: number
  metricLabel: string
  tone: AnalysisReliabilityTone
  tooltip: string
  qualityTheme: QualityThemeId
  scope: FilterScopeSpec
}) {
  const formatMoney = useFormatMoney()
  const formatPercentage = useFormatPercentage()
  const safePercentage = normalizeCoveragePercentage(percentage)
  const styles = RELIABILITY_TONES[tone]
  const percentageLabel = formatPercentage(safePercentage)

  return (
    <CompactDataQualityKpi
      tone={tone}
      tooltip={tooltip}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter normalizes and formats its coverage metric; CompactDataQualityKpi renders the rows and owns quality navigation and live filter badges.
      rows={[
        {
          label: metricLabel,
          value: percentageLabel,
          secondary: i18n.t('ui.analysisreliabilitykpi.analyzedAmount', {
            amount: formatMoney(amount, { style: 'full' }),
          }),
          tone,
        },
      ]}
      qualityTheme={qualityTheme}
      scope={scope}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter translates the summary of its own metric values; CompactDataQualityKpi passes that display-ready label to the shared button.
      ariaLabel={i18n.t(
        'ui.analysisreliabilitykpi.dataQualityValue0Value1Value2OpenDataQuality',
        {
          value0: styles.label,
          value1: percentageLabel,
          value2: metricLabel,
        },
      )}
    />
  )
}

import { CompactDataQualityKpi } from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/analysisReliabilityKpi/CompactDataQualityKpi.feature'
import {
  type QualityTooltipRow,
  RELIABILITY_TONES,
} from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/helpers/presenters/qualityReliabilityPresentation'
import { normalizeCoveragePercentage } from '@/domains/portfolio/features/data-quality/features/assessment/helpers/presenters/normalizeCoveragePercentage'
import type {
  AnalysisReliabilityMetric,
  AnalysisReliabilityTone,
  StatusReliabilityMetric,
} from '@/domains/portfolio/features/data-quality/features/assessment/helpers/quality/analysisReliability/analysisReliability.types'
import type { QualityThemeId } from '@/domains/portfolio/features/data-quality/features/assessment/types/dataQuality.type'
import { type FilterScopeSpec } from '@/domains/portfolio/shared/components/filters/FilterScopeBadges.feature'
import i18n from '@/i18n/i18n'
import { useFormatMoney } from '@/shared/helpers/formatters/useFormatMoney'
import { useFormatPercentage } from '@/shared/helpers/formatters/useFormatPercentage'

export function CombinedAnalysisReliabilityKpi({
  metrics,
  statusMetric,
  tone,
  tooltip,
  qualityTheme,
  scope,
}: {
  metrics: AnalysisReliabilityMetric[]
  statusMetric?: StatusReliabilityMetric
  tone: AnalysisReliabilityTone
  tooltip: string
  qualityTheme: QualityThemeId
  scope: FilterScopeSpec
}) {
  const formatMoney = useFormatMoney()
  const formatPercentage = useFormatPercentage()
  const styles = RELIABILITY_TONES[tone]
  const rows: QualityTooltipRow[] = [
    ...(statusMetric
      ? [
          {
            label: statusMetric.metricLabel,
            value: statusMetric.value,
            tone: statusMetric.tone,
          },
        ]
      : []),
    ...metrics.map((metric) => ({
      label: metric.metricLabel,
      value: formatPercentage(normalizeCoveragePercentage(metric.percentage)),
      secondary: i18n.t('ui.analysisreliabilitykpi.analyzedAmount', {
        amount: formatMoney(metric.amount, { style: 'full' }),
      }),
      tone: metric.tone,
    })),
  ]
  const metricSummary = rows
    .map((row) =>
      i18n.t('ui.analysisreliabilitykpi.metricSummary', {
        value: row.value,
        label: row.label,
      }),
    )
    .join(i18n.t('ui.analysisreliabilitykpi.metricSeparator'))

  return (
    <CompactDataQualityKpi
      tone={tone}
      tooltip={tooltip}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter formats its combined reliability metrics; CompactDataQualityKpi renders the rows and owns quality navigation and live filter badges.
      rows={rows}
      qualityTheme={qualityTheme}
      scope={scope}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter translates the summary of its own metric values; CompactDataQualityKpi passes that display-ready label to the shared button.
      ariaLabel={i18n.t(
        'ui.analysisreliabilitykpi.dataQualityValue0Value1OpenDataQuality',
        {
          value0: styles.label,
          value1: metricSummary,
        },
      )}
    />
  )
}

import { CompactDataQualityKpi } from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/analysisReliabilityKpi/CompactDataQualityKpi.feature'
import { RELIABILITY_TONES } from '@/domains/portfolio/features/data-quality/features/assessment/components/reliability/helpers/presenters/qualityReliabilityPresentation'
import { pipelineReliabilityTone } from '@/domains/portfolio/features/data-quality/features/assessment/helpers/quality/analysisReliability/pipelineReliabilityTone'
import { pipelineStatusLabel } from '@/domains/portfolio/features/data-quality/features/assessment/helpers/quality/analysisReliability/pipelineStatusLabel'
import { type FilterScopeSpec } from '@/domains/portfolio/shared/components/filters/FilterScopeBadges.feature'
import i18n from '@/i18n/i18n'

export function PipelineReliabilityKpi({
  errorCount,
  warningCount,
  loading = false,
  scope,
}: {
  errorCount: number
  warningCount: number
  loading?: boolean
  scope: FilterScopeSpec
}) {
  const tone = pipelineReliabilityTone({ errorCount, warningCount, loading })
  const styles = RELIABILITY_TONES[tone]
  const statusLabel = pipelineStatusLabel({
    errorCount,
    warningCount,
    loading,
  })

  return (
    <CompactDataQualityKpi
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter derives severity from pipeline counts and loading; CompactDataQualityKpi consumes that semantic tone for presentation and navigation.
      tone={tone}
      tooltip={i18n.t(
        'ui.analysisreliabilitykpi.importPositionAndMarketDataAnomaliesRelevantToThe',
      )}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter formats pipeline status and issue counts; CompactDataQualityKpi renders the rows and owns quality navigation and live filter badges.
      rows={[
        {
          label: i18n.t('ui.analysisreliabilitykpi.portfolioData'),
          value: statusLabel,
          secondary: loading
            ? undefined
            : i18n.t('ui.analysisreliabilitykpi.errorWarningSummary', {
                errors: i18n.t('ui.analysisreliabilitykpi.errorCount', {
                  count: errorCount,
                }),
                warnings: i18n.t('ui.analysisreliabilitykpi.warningCount', {
                  count: warningCount,
                }),
              }),
          tone,
        },
      ]}
      qualityTheme="pipeline"
      scope={scope}
      // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This adapter translates the summary of its own metric values; CompactDataQualityKpi passes that display-ready label to the shared button.
      ariaLabel={i18n.t(
        'ui.analysisreliabilitykpi.dataQualityValue0Value1ErrorsAndValue2WarningsIn',
        { value0: styles.label, value1: errorCount, value2: warningCount },
      )}
    />
  )
}

import type { ManualPriceOverride } from '@/domains/portfolio/features/data-quality/shared/types/manualPriceOverride.type'
import type { DashboardFilters } from '@/domains/portfolio/shared/types/dashboardFilters.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

export function scopeManualPriceOverrides(
  overrides: ManualPriceOverride[],
  positions: PositionRow[],
  filters: DashboardFilters,
): ManualPriceOverride[] {
  const selectedIsins = new Set(
    positions.map((position) => position.isin).filter(Boolean),
  )
  const selectedTickers = new Set(
    positions.map((position) => position.ticker).filter(Boolean),
  )
  const selectedNames = new Set(
    positions.map((position) => position.name).filter(Boolean),
  )
  const hasAccountScope =
    filters.accounts.size > 0 || filters.accountTypes.size > 0

  // eslint-disable-next-line complexity -- reviewed: 2026-10-27; Date overlap and alternative asset identifiers define one manual-price visibility predicate.
  return overrides.filter((override) => {
    if (
      filters.dateFrom &&
      override.date_to &&
      override.date_to < filters.dateFrom
    )
      return false
    if (
      filters.dateTo &&
      override.date_from &&
      override.date_from > filters.dateTo
    )
      return false
    if (!hasAccountScope) return true
    return (
      (!!override.isin && selectedIsins.has(override.isin)) ||
      (!!override.ticker && selectedTickers.has(override.ticker)) ||
      (!!override.name && selectedNames.has(override.name))
    )
  })
}

import type { PipelineError } from '@/domains/portfolio/features/data-quality/shared/types/pipelineError.type'
import type { DashboardFilters } from '@/domains/portfolio/shared/types/dashboardFilters.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import { toCalendarMonth } from '@/shared/helpers/mappers/toCalendarMonth'

export function scopePipelineErrors(
  errors: PipelineError[],
  positions: PositionRow[],
  filters: DashboardFilters,
): PipelineError[] {
  const selectedAccounts = new Set(
    positions.map((position) => position.account),
  )
  const selectedIsins = new Set(
    positions.map((position) => position.isin).filter(Boolean),
  )
  const selectedTickers = new Set(
    positions.map((position) => position.ticker).filter(Boolean),
  )
  const hasPositionScope =
    filters.accounts.size > 0 ||
    filters.accountTypes.size > 0 ||
    filters.operationTypes.size > 0

  // eslint-disable-next-line complexity -- reviewed: 2026-10-27; Month, account and identifier precedence define one anomaly-scope predicate, including unattributable pipeline issues.
  return errors.filter((error) => {
    const month = errorMonth(error.date)
    if (month && filters.dateFrom && month < toCalendarMonth(filters.dateFrom))
      return false
    if (month && filters.dateTo && month > toCalendarMonth(filters.dateTo))
      return false

    if (!hasPositionScope) return true
    if (error.account) return selectedAccounts.has(error.account)
    if (error.isin) return selectedIsins.has(error.isin)
    if (error.ticker) return selectedTickers.has(error.ticker)

    // Pipeline-wide anomalies cannot be attributed more narrowly, so they
    // remain visible even when an account or position filter is active.
    return true
  })
}

function errorMonth(date: Date | null): string | null {
  return date ? toCalendarMonth(date) : null
}

import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import type { RawIsinData } from '@/domains/portfolio/shared/types/rawIsinData.type'

import type { AccountCoverage } from './computeAllocationCoverage.types'

/** Current (active, positive-value) positions split into allocated vs
 * unallocated amounts, grouped by account.
 */
// eslint-disable-next-line complexity -- reviewed: 2026-10-27; One account accumulator partitions active value into mapped, missing and inapplicable coverage.
export function computeAllocationCoverageByAccount(
  positions: PositionRow[],
  rawData: RawIsinData,
): AccountCoverage[] {
  const allocated = allocatedKeys(rawData)
  const byAccount = new Map<string, AccountCoverage>()

  for (const p of positions) {
    if (p.status !== 'active') continue
    const value = p.total_value ?? 0
    if (value <= 0) continue

    const cur = byAccount.get(p.account) ?? {
      account: p.account,
      allocated: 0,
      unallocated: 0,
      notApplicable: 0,
    }
    if (isAssetAnalysisApplicablePosition(p)) {
      const key = p.isin || `NC-${p.name}`
      if (allocated.has(key)) cur.allocated += value
      else cur.unallocated += value
    } else {
      cur.notApplicable += value
    }
    byAccount.set(p.account, cur)
  }

  return [...byAccount.values()].toSorted(
    (a, b) =>
      b.allocated +
      b.unallocated +
      b.notApplicable -
      (a.allocated + a.unallocated + a.notApplicable),
  )
}

/** Keys ("isin" column of positions_*_by_isin.csv, "NC-<name>" when no ISIN)
 * that have an allocation match in at least one dimension's latest row --
 * mirrors _isin_or_synthetic_key in positions_allocation.py.
 */
function allocatedKeys(rawData: RawIsinData): Set<string> {
  const keys = new Set<string>()
  for (const dim of ['geo', 'secteur', 'currency', 'classe'] as const) {
    for (const row of rawData[dim]) keys.add(row.isin)
  }
  return keys
}

import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import type { RawIsinData } from '@/domains/portfolio/shared/types/rawIsinData.type'

import type {
  AllocationCoverageIssue,
  DimensionCoverage,
} from './computeAllocationCoverage.types'

/** Monetary allocation coverage per dimension. Explicit `nc` weights and
 * completely missing rows are both counted as unallocated and remain
 * traceable to the responsible current position.
 */
export function computeAllocationCoverageByDimension(
  positions: PositionRow[],
  rawData: RawIsinData,
): DimensionCoverage[] {
  return (['geo', 'secteur', 'currency', 'classe'] as const).map(
    // eslint-disable-next-line complexity -- reviewed: 2026-10-27; One dimension accumulator combines the latest breakdown, missing ratio and corresponding issue totals.
    (dimension) => {
      const latestByKey = new Map<
        string,
        (typeof rawData)[typeof dimension][number]
      >()
      for (const row of rawData[dimension]) {
        const current = latestByKey.get(row.isin)
        if (!current || row.snapshot_date > current.snapshot_date)
          latestByKey.set(row.isin, row)
      }
      let allocated = 0
      let unallocated = 0
      const issues = new Map<string, AllocationCoverageIssue>()
      for (const position of positions) {
        const value =
          position.status === 'active'
            ? Math.max(0, position.total_value ?? 0)
            : 0
        if (value <= 0) continue
        if (!isAssetAnalysisApplicablePosition(position)) continue
        const key = position.isin || `NC-${position.name}`
        const allocation = latestByKey.get(key)
        const allocationTotal = allocation
          ? Object.values(allocation.values).reduce(
              (sum, amount) => sum + amount,
              0,
            )
          : 0
        const ncRatio =
          allocationTotal > 0
            ? Math.min(
                1,
                Math.max(0, (allocation?.values.nc ?? 0) / allocationTotal),
              )
            : 1
        const missing = value * ncRatio
        allocated += value - missing
        unallocated += missing
        if (missing > 0.01) {
          const current = issues.get(key) ?? {
            id: key,
            name: position.name,
            value: 0,
            unallocated: 0,
          }
          current.value += value
          current.unallocated += missing
          issues.set(key, current)
        }
      }
      return {
        dimension,
        allocated,
        unallocated,
        issues: [...issues.values()].toSorted(
          (a, b) => b.unallocated - a.unallocated,
        ),
      }
    },
  )
}

import type { FundCoverageReport } from '@/domains/portfolio/features/data-quality/features/assessment/types/fundCoverageReport.type'
import type { FundSnapshot } from '@/domains/portfolio/features/data-quality/features/assessment/types/fundSnapshot.type'
import type { FundUnresolved } from '@/domains/portfolio/features/data-quality/features/assessment/types/fundUnresolved.type'
import { isFundPosition } from '@/domains/portfolio/shared/helpers/mappers/buildFundHoldingsViewModel/isFundPosition'
import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import type { FundHolding } from '@/domains/portfolio/shared/types/fundHolding.type'
import type { FundHoldingStatus } from '@/domains/portfolio/shared/types/fundHoldingStatus.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

import type { ScopedFundQualityData } from './scopeFundQualityData.types'

export function scopeFundQualityData(
  positions: PositionRow[],
  holdings: FundHolding[],
  statuses: FundHoldingStatus[],
  snapshots: FundSnapshot[],
  unresolved: FundUnresolved[],
  baseReport: FundCoverageReport | null,
): ScopedFundQualityData {
  const notApplicableValue = positions
    .filter(
      (position) =>
        positiveValue(position) > 0 &&
        !isAssetAnalysisApplicablePosition(position),
    )
    .reduce((sum, position) => sum + positiveValue(position), 0)
  const activePositions = positions.filter(
    (position) =>
      positiveValue(position) > 0 &&
      isAssetAnalysisApplicablePosition(position),
  )
  const statusByPosition = new Map<PositionRow, FundHoldingStatus>()
  for (const position of activePositions) {
    const status = statuses.find((candidate) =>
      positionMatchesStatus(position, candidate),
    )
    if (status) statusByPosition.set(position, status)
  }

  const scopedStatuses = statuses.flatMap((status) => {
    const marketValue = activePositions
      .filter((position) => positionMatchesStatus(position, status))
      .reduce((sum, position) => sum + positiveValue(position), 0)
    if (marketValue <= 0) return []
    const explainedValue = marketValue * clampRatio(status.explainedPct)
    const residualValue = marketValue * clampRatio(status.residualPct)
    return [{ ...status, marketValue, explainedValue, residualValue }]
  })

  const selectedParentKeys = new Set(
    scopedStatuses
      .flatMap((status) => [
        status.parentId,
        status.parentIsin,
        status.parentTicker,
        status.parentName,
      ])
      .filter(Boolean),
  )
  const scopedHoldings = holdings.filter((holding) =>
    activePositions.some((position) =>
      positionMatchesHolding(position, holding),
    ),
  )
  const scopedSnapshots = snapshots.filter((snapshot) =>
    selectedParentKeys.has(snapshot.fundId),
  )
  const scopedUnresolved = unresolved.filter((item) =>
    selectedParentKeys.has(item.parentId),
  )

  const { fundValue, directIdentifiedValue, opaqueValue, statuslessFundIds } =
    classifyFundPositions(activePositions, statusByPosition)

  const portfolioValue = activePositions.reduce(
    (sum, position) => sum + positiveValue(position),
    0,
  )
  const decomposedValue = scopedStatuses.reduce(
    (sum, status) => sum + status.explainedValue,
    0,
  )
  const highConfidenceExplainedValue = scopedStatuses
    .filter(
      (status) => status.qualityTier === 'A' || status.qualityTier === 'B',
    )
    .reduce((sum, status) => sum + status.explainedValue, 0)
  const undisclosedFundValue = Math.max(0, fundValue - decomposedValue)
  const fundCoveragePct =
    fundValue > 0 ? (highConfidenceExplainedValue / fundValue) * 100 : 100
  const portfolioCoveragePct =
    portfolioValue > 0
      ? ((directIdentifiedValue + highConfidenceExplainedValue) /
          portfolioValue) *
        100
      : 0

  const {
    coverageGatePass,
    topFundsGatePass,
    exactProxyGatePass,
    repeatabilityGatePass,
    feasibilityStatus,
  } = evaluateFundQualityGates(scopedStatuses, fundValue, fundCoveragePct)

  return {
    holdings: scopedHoldings,
    statuses: scopedStatuses,
    snapshots: scopedSnapshots,
    unresolved: scopedUnresolved,
    notApplicableValue,
    report: baseReport
      ? {
          asOfDate: baseReport?.asOfDate ?? '',
          portfolioValue,
          fundValue,
          directIdentifiedValue,
          opaqueValue,
          decomposedValue,
          highConfidenceExplainedValue,
          undisclosedFundValue,
          fundCoveragePct,
          portfolioCoveragePct,
          coverageGatePass,
          topFundsGatePass,
          exactProxyGatePass,
          repeatabilityGatePass,
          feasibilityStatus,
          fundCount: scopedStatuses.length + statuslessFundIds.size,
          issueCount: scopedStatuses.filter(
            (status) => status.validationStatus !== 'ok',
          ).length,
        }
      : null,
  }
}

function positiveValue(position: PositionRow): number {
  return position.status === 'active'
    ? Math.max(0, position.total_value ?? 0)
    : 0
}

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; ISIN, ticker and name are alternative identifiers in one fund-status match predicate.
function positionMatchesStatus(
  position: PositionRow,
  status: FundHoldingStatus,
): boolean {
  return (
    (!!position.isin &&
      (position.isin === status.parentIsin ||
        position.isin === status.parentId)) ||
    (!!position.ticker &&
      (position.ticker === status.parentTicker ||
        position.ticker === status.parentId)) ||
    (!!position.name &&
      (position.name === status.parentName ||
        position.name === status.parentId))
  )
}

function positionMatchesHolding(
  position: PositionRow,
  holding: FundHolding,
): boolean {
  return (
    (!!position.isin && position.isin === holding.parentIsin) ||
    (!!position.ticker && position.ticker === holding.parentTicker) ||
    (!!position.name && position.name === holding.parentName)
  )
}

function clampRatio(percentage: number): number {
  return Math.max(0, Math.min(1, percentage / 100))
}

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; One exclusive classification partitions fund, direct and opaque values without distributing its accumulator.
function classifyFundPositions(
  activePositions: PositionRow[],
  statusByPosition: Map<PositionRow, FundHoldingStatus>,
) {
  let fundValue = 0
  let directIdentifiedValue = 0
  let opaqueValue = 0
  const statuslessFundIds = new Set<string>()
  for (const position of activePositions) {
    const value = positiveValue(position)
    const status = statusByPosition.get(position)
    if (status || isFundPosition(position)) {
      fundValue += value
      if (!status)
        statuslessFundIds.add(position.isin || position.ticker || position.name)
    } else if (position.isin || position.ticker) {
      directIdentifiedValue += value
    } else {
      opaqueValue += value
    }
  }

  return { fundValue, directIdentifiedValue, opaqueValue, statuslessFundIds }
}

function evaluateFundQualityGates(
  scopedStatuses: FundHoldingStatus[],
  fundValue: number,
  fundCoveragePct: number,
) {
  const ranked = [...scopedStatuses]
    .toSorted((a, b) => b.marketValue - a.marketValue)
    .slice(0, 7)
  const coverageGatePass = fundValue === 0 || fundCoveragePct >= 85
  const topFundsGatePass =
    ranked.length === 0 ||
    ranked.every(
      (status) =>
        (status.qualityTier === 'A' || status.qualityTier === 'B') &&
        status.explainedPct >= 98,
    )
  const exactProxyGatePass = scopedStatuses
    .filter((status) => status.qualityTier === 'B')
    .every((status) => !!status.indexName.trim() && !!status.proxyIsin.trim())
  const repeatabilityGatePass =
    ranked.length === 0 || ranked.every((status) => status.refreshStreak >= 2)
  const qualityGatesPass =
    coverageGatePass && topFundsGatePass && exactProxyGatePass
  let feasibilityStatus: FundCoverageReport['feasibilityStatus'] = 'limited'
  if (qualityGatesPass) {
    feasibilityStatus = repeatabilityGatePass
      ? 'passed'
      : 'pending_repeatability'
  }

  return {
    coverageGatePass,
    topFundsGatePass,
    exactProxyGatePass,
    repeatabilityGatePass,
    feasibilityStatus,
  }
}

import { useMemo, useState } from 'react'

import type { PipelineErrorSortColumn } from '@/domains/portfolio/features/data-quality/features/errors/helpers/mappers/buildPipelineErrorsViewModel/buildPipelineErrorsViewModel.types'
import { PIPELINE_ERROR_TYPE_LABELS } from '@/domains/portfolio/features/data-quality/features/errors/helpers/mappers/buildPipelineErrorsViewModel/pipelineErrorTypeLabels'
import { useBuildPipelineErrorsViewModel } from '@/domains/portfolio/features/data-quality/features/errors/helpers/mappers/buildPipelineErrorsViewModel/useBuildPipelineErrorsViewModel'
import type { PipelineError } from '@/domains/portfolio/features/data-quality/shared/types/pipelineError.type'
