import { Text } from '@/shared/ui/Text.view'

export function CumulativeConcentrationChart({
  data,
  description,
  effectiveDate,
}: {
  data: CumulativeConcentrationPoint[]
  description?: string
  effectiveDate?: Date | null
}) {
  const formatPercentage = useFormatPercentage()
  const [activePoint, setActivePoint] =
    useState<CumulativeConcentrationPoint | null>(null)
  const crosshair = cumulativeConcentrationCrosshair(activePoint)
  const maxRank = data.at(-1)?.rank ?? 1

  function updateActivePoint(state: MouseHandlerDataParam) {
    if (!state.isTooltipActive || state.activeTooltipIndex == null) {
      setActivePoint(null)
      return
    }
    const index = Number(state.activeTooltipIndex)
    setActivePoint(Number.isInteger(index) ? (data[index] ?? null) : null)
  }

  return (
    <Surface variant="chart">
      <Layout spaceAfter="default">
        <Text as="h2" variant="label" tone="secondary">
          <Inline as="span" align="center">
            {i18n.t('ui.cumulativeconcentrationchart.cumulativeConcentration')}
            <ScopedInfoTooltip
              // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This chart owns the fallback description and snapshot date; ScopedInfoTooltip only renders that specification with live filter badges.
              text={
                description ??
                i18n.t(
                  'ui.cumulativeconcentrationchart.shareOfTheApplicablePortfolioHeldInTheLargest',
                )
              }
              // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This chart owns the fallback description and snapshot date; ScopedInfoTooltip only renders that specification with live filter badges.
              scope={{
                account: 'filterable',
                period: 'as-of',
                effectiveDate,
              }}
            />
          </Inline>
        </Text>
        <Layout spaceBefore="compact">
          <Text as="p" variant="caption" tone="subtle">
            {description ??
              i18n.t(
                'ui.cumulativeconcentrationchart.shareOfTheApplicablePortfolioHeldInTheLargest',
              )}
          </Text>
        </Layout>
      </Layout>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart
          data={data}
          margin={{ top: 8, right: 12, left: 0, bottom: 4 }}
          onMouseMove={updateActivePoint}
          onMouseLeave={() => setActivePoint(null)}
          onTouchMove={updateActivePoint}
          onTouchEnd={() => setActivePoint(null)}
        >
          <ChartGrid />
          <ChartXAxis
            dataKey="rank"
            type="number"
            domain={[1, maxRank]}
            allowDecimals={false}
          />
          <ChartYAxis
            domain={[0, 100]}
            ticks={[0, 25, 50, 75, 100]}
            tickFormatter={(value: number) =>
              formatPercentage(Number(value), { decimals: 'auto' })
            }
            width={42}
          />
          {crosshair && (
            <>
              <ChartReference x={crosshair.x} kind="crosshair" />
              <ChartReference y={crosshair.y} kind="crosshair" />
            </>
          )}
          <Tooltip
            content={<CumulativeConcentrationTooltip />}
            cursor={false}
          />
          <SeriesLine
            type="linear"
            dataKey="cumulativeWeight"
            tone={PORTFOLIO_CHART_TONES.risk}
            weight="emphasized"
            markers="hidden"
            hover="series"
            motion="none"
          />
        </LineChart>
      </ResponsiveContainer>
      <Layout spaceBefore="compact">
        <Text as="div" variant="micro" tone="subtle" align="center">
          {i18n.t('ui.cumulativeconcentrationchart.numberOfAssets')}
        </Text>
      </Layout>
    </Surface>
  )
}

import { isFundPosition } from '@/domains/portfolio/shared/helpers/mappers/buildFundHoldingsViewModel/isFundPosition'
import { resolveAssetName } from '@/domains/portfolio/shared/helpers/mappers/resolveAssetName'
import { indexFundHoldingsByParent } from '@/domains/portfolio/shared/helpers/selectors/indexFundHoldingsByParent'
import type { FundHolding } from '@/domains/portfolio/shared/types/fundHolding.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

import type { ConcentrationSummary } from './concentrationCalculations.types'
import { isValuedAnalysisPosition } from './isValuedAnalysisPosition'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; Direct, decomposed, undisclosed and opaque positions share one conservation accumulator and ranking.
export function computeConcentration(
  positions: PositionRow[],
  fundHoldings: FundHolding[] = [],
): ConcentrationSummary {
  const byAsset = new Map<
    string,
    { label: string; name: string; value: number }
  >()
  const holdingsByParent = indexFundHoldingsByParent(fundHoldings)

  let selectedValue = 0
  let identifiedValue = 0
  let undisclosedValue = 0
  let opaqueValue = 0

  function addAsset(key: string, label: string, name: string, value: number) {
    const current = byAsset.get(key) ?? { label, name, value: 0 }
    current.value += value
    byAsset.set(key, current)
  }

  for (const position of positions) {
    if (!isValuedAnalysisPosition(position)) continue
    const positionValue = position.total_value ?? 0
    selectedValue += positionValue

    const lookThrough =
      holdingsByParent.get(position.isin) ??
      holdingsByParent.get(position.ticker)
    if (lookThrough != null && lookThrough.length > 0) {
      const exposure = addFundConcentration(
        lookThrough,
        positionValue,
        addAsset,
      )
      identifiedValue += exposure.identified
      undisclosedValue += exposure.undisclosed
      continue
    }

    // Rows without a market identifier are account-level valuations (PEE,
    // PER, bank accounts, private-equity envelopes), not underlying assets.
    // Keep them out of the ranking instead of presenting the account as a
    // holding. Identified non-fund securities remain valid direct exposure.
    const key = position.isin || position.ticker
    if (!key) {
      opaqueValue += positionValue
      continue
    }
    if (isFundPosition(position)) {
      undisclosedValue += positionValue
      continue
    }
    addAsset(key, resolveAssetName(position, key), position.name, positionValue)
    identifiedValue += positionValue
  }

  const allHoldings = [...byAsset.values()]
    .toSorted((a, b) => b.value - a.value)
    .map((holding) => ({
      ...holding,
      value: Math.round(holding.value),
      weight: selectedValue > 0 ? (holding.value / selectedValue) * 100 : 0,
    }))
  const holdings = allHoldings.slice(0, 10)

  return {
    topHoldingPct: holdings[0]?.weight ?? 0,
    topFivePct: holdings
      .slice(0, 5)
      .reduce((sum, holding) => sum + holding.weight, 0),
    topTenPct: holdings.reduce((sum, holding) => sum + holding.weight, 0),
    topTenValue: holdings.reduce((sum, holding) => sum + holding.value, 0),
    coveragePct:
      selectedValue > 0 ? (identifiedValue / selectedValue) * 100 : 0,
    identifiedValue,
    undisclosedValue,
    opaqueValue,
    selectedValue,
    holdingCount: allHoldings.length,
    allHoldings,
    holdings,
  }
}

function addFundConcentration(
  lookThrough: FundHolding[],
  positionValue: number,
  addAsset: (key: string, label: string, name: string, value: number) => void,
) {
  const disclosedWeight = lookThrough.reduce(
    (sum, holding) => sum + holding.weight,
    0,
  )
  const scale = disclosedWeight > 1 ? 1 / disclosedWeight : 1
  for (const holding of lookThrough) {
    addAsset(
      holding.issuerId || holding.holdingId,
      holding.issuerName || holding.holdingName,
      holding.issuerName || holding.holdingName,
      positionValue * holding.weight * scale,
    )
  }
  const explainedWeight = Math.min(1, disclosedWeight)
  return {
    identified: positionValue * explainedWeight,
    undisclosed: positionValue * (1 - explainedWeight),
  }
}

import { resolveAssetName } from '@/domains/portfolio/shared/helpers/mappers/resolveAssetName'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

import type { ConcentrationSummary } from './concentrationCalculations.types'
import { isValuedAnalysisPosition } from './isValuedAnalysisPosition'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; One held-asset aggregation normalizes identity, weights and the top-ten summary against the same total.
export function computeHeldAssetConcentration(
  positions: PositionRow[],
): ConcentrationSummary {
  const byAsset = new Map<
    string,
    { label: string; name: string; value: number }
  >()

  for (const position of positions) {
    if (!isValuedAnalysisPosition(position)) continue
    // This is deliberately the allocation-file grain: the instrument or
    // product actually held, aggregated across accounts when its market
    // identifier is shared. Account-valued products fall back to their name.
    const key = position.isin || position.ticker || position.name
    const current = byAsset.get(key) ?? {
      label: resolveAssetName(position, key),
      name: position.name,
      value: 0,
    }
    current.value += position.total_value ?? 0
    byAsset.set(key, current)
  }

  const total = [...byAsset.values()].reduce(
    (sum, holding) => sum + holding.value,
    0,
  )
  const allHoldings = [...byAsset.values()]
    .toSorted((a, b) => b.value - a.value)
    .map((holding) => ({
      ...holding,
      value: Math.round(holding.value),
      weight: total > 0 ? (holding.value / total) * 100 : 0,
    }))
  const holdings = allHoldings.slice(0, 10)

  return {
    topHoldingPct: holdings[0]?.weight ?? 0,
    topFivePct: holdings
      .slice(0, 5)
      .reduce((sum, holding) => sum + holding.weight, 0),
    topTenPct: holdings.reduce((sum, holding) => sum + holding.weight, 0),
    topTenValue: holdings.reduce((sum, holding) => sum + holding.value, 0),
    coveragePct: total > 0 ? 100 : 0,
    identifiedValue: total,
    undisclosedValue: 0,
    opaqueValue: 0,
    selectedValue: total,
    holdingCount: byAsset.size,
    allHoldings,
    holdings,
  }
}

// eslint-disable-next-line local/review-shared-feature-sharing -- reviewed: 2026-10-27; The shell distributes the prepared scope to both allocation and concentration. See SHARED_OWNERSHIP_AUDIT.md.
import type { DiversificationInputs } from '@/domains/portfolio/features/diversification/shared/types/diversificationInputs.type'
import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

import { excludeNonApplicableAllocationData } from './scopeDiversificationData/excludeNonApplicableAllocationData'
import { scopeRawAllocationData } from './scopeDiversificationData/scopeRawAllocationData'

export function prepareDiversificationScope(
  inputs: Pick<
    DiversificationInputs,
    'positions' | 'rawData' | 'accountFilters'
  >,
) {
  const applicablePositions = inputs.positions.filter(
    isAssetAnalysisApplicablePosition,
  )
  const scopedRawData = excludeNonApplicableAllocationData(
    scopeRawAllocationData(inputs.rawData, inputs.accountFilters),
    inputs.positions,
  )
  return {
    applicablePositions,
    scopedRawData,
    hasCurrentData: [
      scopedRawData.geo,
      scopedRawData.secteur,
      scopedRawData.currency,
      scopedRawData.classe,
    ].some((rows) => rows.length > 0),
    hasSelectedValue: inputs.positions.some(hasActiveValue),
    hasApplicableValue: applicablePositions.some(hasActiveValue),
  }
}

function hasActiveValue(position: PositionRow): boolean {
  return position.status === 'active' && (position.total_value ?? 0) > 0
}

// eslint-disable-next-line local/review-shared-feature-sharing -- reviewed: 2026-10-27; The shell distributes the prepared scope to both allocation and concentration. See SHARED_OWNERSHIP_AUDIT.md.
import { accountFilterId } from '@/domains/portfolio/shared/helpers/filters/accountFilter/accountFilterId'
import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import type { RawIsinData } from '@/domains/portfolio/shared/types/rawIsinData.type'
import type { RawIsinRow } from '@/domains/portfolio/shared/types/rawIsinRow.type'

export function excludeNonApplicableAllocationData(
  rawData: RawIsinData,
  positions: PositionRow[],
): RawIsinData {
  const excludedAccounts = new Set(
    positions
      .filter((position) => !isAssetAnalysisApplicablePosition(position))
      .map(accountFilterId),
  )
  if (excludedAccounts.size === 0) return rawData
  const isApplicable = (row: RawIsinRow) =>
    !row.account ||
    !excludedAccounts.has(
      accountFilterId({
        account: row.account,
        account_type: row.account_type,
      }),
    )
  return {
    geo: rawData.geo.filter(isApplicable),
    secteur: rawData.secteur.filter(isApplicable),
    currency: rawData.currency.filter(isApplicable),
    classe: rawData.classe.filter(isApplicable),
    loading: rawData.loading,
  }
}

// eslint-disable-next-line local/review-shared-feature-sharing -- reviewed: 2026-10-27; The shell distributes the prepared scope to both allocation and concentration. See SHARED_OWNERSHIP_AUDIT.md.
import { accountFilterId } from '@/domains/portfolio/shared/helpers/filters/accountFilter/accountFilterId'
import type { RawIsinData } from '@/domains/portfolio/shared/types/rawIsinData.type'
import type { RawIsinRow } from '@/domains/portfolio/shared/types/rawIsinRow.type'

export function scopeRawAllocationData(
  rawData: RawIsinData,
  accounts: Set<string>,
): RawIsinData {
  if (accounts.size === 0) return rawData
  const inScope = (row: RawIsinRow) =>
    !!row.account &&
    accounts.has(
      accountFilterId({
        account: row.account,
        account_type: row.account_type,
      }),
    )
  return {
    geo: rawData.geo.filter(inScope),
    secteur: rawData.secteur.filter(inScope),
    currency: rawData.currency.filter(inScope),
    classe: rawData.classe.filter(inScope),
    loading: rawData.loading,
  }
}

import type {
  IssuerExposure,
  SecurityExposure,
} from '@/domains/portfolio/features/holdings/features/fund-look-through/helpers/mappers/issuerExposures/buildFundHoldingsViewModel.types'
import { buildIssuerExposures } from '@/domains/portfolio/features/holdings/features/fund-look-through/helpers/mappers/issuerExposures/buildIssuerExposures'
import type { FundHolding } from '@/domains/portfolio/shared/types/fundHolding.type'
import type { FundHoldingStatus } from '@/domains/portfolio/shared/types/fundHoldingStatus.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; Exact fund selection, free-text search and expansion build one exposure-explorer result from the same issuer set.
export function buildFundExposureViewModel({
  expanded,
  holdings,
  positions,
  query,
  sort,
  statuses,
}: BuildFundExposureViewModelInput) {
  const needle = query.trim().toLocaleLowerCase()
  const selectedFundName = needle
    ? (positions.find(
        (position) =>
          position.name.toLocaleLowerCase() === needle &&
          matchesFundStatus(position, statuses),
      )?.name ?? '')
    : ''
  const scopedPositions = selectedFundName
    ? positions.filter((position) => position.name === selectedFundName)
    : positions
  const parentIds = new Set(
    scopedPositions
      .flatMap((position) => [position.isin, position.ticker])
      .filter(Boolean),
  )
  const scopedHoldings = selectedFundName
    ? holdings.filter(
        (holding) =>
          holding.parentName === selectedFundName ||
          parentIds.has(holding.parentIsin) ||
          parentIds.has(holding.parentTicker),
      )
    : holdings
  const exposures = buildIssuerExposures(
    scopedPositions,
    scopedHoldings,
    statuses,
  )
  const filtered =
    needle && !selectedFundName
      ? exposures.filter(
          (issuer) =>
            issuer.name.toLocaleLowerCase().includes(needle) ||
            issuer.id.toLocaleLowerCase().includes(needle) ||
            issuer.securities.some((security) =>
              security.name.toLocaleLowerCase().includes(needle),
            ) ||
            issuer.funds.some((fund) =>
              fund.toLocaleLowerCase().includes(needle),
            ),
        )
      : exposures
  const displayed = [...filtered].toSorted(
    sort === 'value'
      ? (left, right) => right.value - left.value
      : (left, right) => left.name.localeCompare(right.name),
  )
  const rows: ExposureRow[] = displayed.flatMap((issuer) => [
    { kind: 'issuer' as const, issuer, open: expanded.has(issuer.id) },
    ...(expanded.has(issuer.id)
      ? issuer.securities.flatMap((security): ExposureRow[] => [
          { kind: 'security', issuer, security },
          ...(security.sources.length > 1
            ? security.sources.map((source) => ({
                kind: 'source' as const,
                issuer,
                security,
                fund: source.fund,
                value: source.value,
              }))
            : []),
        ])
      : []),
  ])

  return {
    displayed,
    rows,
    securityCount: displayed.reduce(
      (sum, issuer) => sum + issuer.securities.length,
      0,
    ),
    totalIssuerCount: exposures.length,
  }
}

export type FundExposureSort = 'value' | 'name'

export type ExposureRow =
  | { kind: 'issuer'; issuer: IssuerExposure; open: boolean }
  | { kind: 'security'; issuer: IssuerExposure; security: SecurityExposure }
  | {
      kind: 'source'
      issuer: IssuerExposure
      security: SecurityExposure
      fund: string
      value: number
    }

type BuildFundExposureViewModelInput = {
  expanded: Set<string>
  holdings: FundHolding[]
  positions: PositionRow[]
  query: string
  sort: FundExposureSort
  statuses: FundHoldingStatus[]
}

function matchesFundStatus(
  position: PositionRow,
  statuses: FundHoldingStatus[],
): boolean {
  return statuses.some(
    (status) =>
      status.parentId === (position.isin || position.ticker) ||
      (!!position.isin && status.parentIsin === position.isin) ||
      (!!position.ticker && status.parentTicker === position.ticker),
  )
}

import type { IssuerExposure } from '@/domains/portfolio/features/holdings/features/fund-look-through/helpers/mappers/issuerExposures/buildFundHoldingsViewModel.types'
import { isFundPosition } from '@/domains/portfolio/shared/helpers/mappers/buildFundHoldingsViewModel/isFundPosition'
import { isAssetAnalysisApplicablePosition } from '@/domains/portfolio/shared/helpers/quality/accountApplicability'
import { indexFundHoldingsByParent } from '@/domains/portfolio/shared/helpers/selectors/indexFundHoldingsByParent'
import type { FundHolding } from '@/domains/portfolio/shared/types/fundHolding.type'
import type { FundHoldingStatus } from '@/domains/portfolio/shared/types/fundHoldingStatus.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import i18n from '@/i18n/i18n'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; Canonical issuers and source funds share one accumulation pass; splitting would distribute the same mutable ledger.
export function buildIssuerExposures(
  positions: PositionRow[],
  holdings: FundHolding[],
  statuses: FundHoldingStatus[] = [],
): IssuerExposure[] {
  const applicablePositions = positions.filter(
    isAssetAnalysisApplicablePosition,
  )
  const byParent = indexFundHoldingsByParent(holdings)

  const canonicalIssuer = createCanonicalIssuerResolver(holdings)

  type MutableSecurity = {
    id: string
    name: string
    value: number
    funds: Map<string, number>
  }
  type MutableIssuer = {
    id: string
    name: string
    value: number
    securities: Map<string, MutableSecurity>
    funds: Map<string, number>
  }
  const issuers = new Map<string, MutableIssuer>()
  const compositeIds = new Set(
    statuses
      .flatMap((status) => [
        status.parentId,
        status.parentIsin,
        status.parentTicker,
      ])
      .filter(Boolean),
  )
  const total = applicablePositions.reduce(
    (sum, position) =>
      position.status === 'active'
        ? sum + Math.max(0, position.total_value ?? 0)
        : sum,
    0,
  )

  const add = (
    issuerId: string,
    issuerName: string,
    securityId: string,
    securityName: string,
    value: number,
    fundName: string,
  ) => {
    const issuer = issuers.get(issuerId) ?? {
      id: issuerId,
      name: issuerName,
      value: 0,
      securities: new Map<string, MutableSecurity>(),
      funds: new Map<string, number>(),
    }
    issuer.value += value
    if (fundName)
      issuer.funds.set(fundName, (issuer.funds.get(fundName) ?? 0) + value)
    const security = issuer.securities.get(securityId) ?? {
      id: securityId,
      name: securityName,
      value: 0,
      funds: new Map<string, number>(),
    }
    security.value += value
    if (fundName)
      security.funds.set(fundName, (security.funds.get(fundName) ?? 0) + value)
    issuer.securities.set(securityId, security)
    issuers.set(issuerId, issuer)
  }

  for (const position of applicablePositions) {
    const positionValue =
      position.status === 'active' ? Math.max(0, position.total_value ?? 0) : 0
    if (positionValue <= 0) continue
    const fundRows =
      byParent.get(position.isin) ?? byParent.get(position.ticker)
    if (fundRows != null && fundRows.length > 0) {
      const totalWeight = fundRows.reduce((sum, row) => sum + row.weight, 0)
      const scale = totalWeight > 1 ? 1 / totalWeight : 1
      for (const holding of fundRows) {
        const issuer = canonicalIssuer(holding.issuerId || holding.holdingId)
        add(
          issuer.id,
          issuer.name || holding.issuerName || holding.holdingName,
          holding.holdingId,
          holding.holdingName,
          positionValue * holding.weight * scale,
          position.name,
        )
      }
      continue
    }
    const directId = position.isin || position.ticker
    if (directId && !compositeIds.has(directId) && !isFundPosition(position)) {
      add(
        directId,
        position.name,
        directId,
        position.name,
        positionValue,
        i18n.t('ui.buildfundholdingsviewmodel.direct'),
      )
    }
  }

  return [...issuers.values()]
    .map((issuer) => ({
      id: issuer.id,
      name: issuer.name,
      value: issuer.value,
      weight: total > 0 ? (issuer.value / total) * 100 : 0,
      funds: [...issuer.funds.keys()].toSorted(),
      sources: [...issuer.funds]
        .map(([fund, value]) => ({ fund, value }))
        .toSorted((a, b) => b.value - a.value),
      securities: [...issuer.securities.values()]
        .map((security) => ({
          id: security.id,
          name: security.name,
          value: security.value,
          funds: [...security.funds.keys()].toSorted(),
          sources: [...security.funds]
            .map(([fund, value]) => ({ fund, value }))
            .toSorted((a, b) => b.value - a.value),
        }))
        .toSorted((a, b) => b.value - a.value),
    }))
    .toSorted((a, b) => b.value - a.value)
}

function createCanonicalIssuerResolver(holdings: FundHolding[]) {
  // Some official files truncate long issuer names while others spell them
  // out. Merge only strong normalized-prefix matches; market identifiers
  // (ISIN-like values) remain authoritative and are never fuzzily merged.
  const issuerNames = new Map<string, string>()
  for (const holding of holdings)
    issuerNames.set(holding.issuerId, holding.issuerName)
  const normalizedIssuerIds = [...issuerNames.keys()].filter(
    (id) => !/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(id),
  )
  const canonicalIssuerById = new Map<string, string>()
  for (const id of normalizedIssuerIds) {
    const matches = normalizedIssuerIds.filter(
      (candidate) =>
        Math.min(candidate.length, id.length) >= 12 &&
        (candidate.startsWith(id) || id.startsWith(candidate)),
    )
    canonicalIssuerById.set(
      id,
      matches.reduce<string | undefined>(
        (longest, candidate) =>
          longest == null || candidate.length > longest.length
            ? candidate
            : longest,
        undefined,
      ) ?? id,
    )
  }
  const canonicalIssuer = (id: string): { id: string; name: string } => {
    const canonicalId = canonicalIssuerById.get(id) ?? id
    return {
      id: canonicalId,
      name: issuerNames.get(canonicalId) ?? issuerNames.get(id) ?? id,
    }
  }

  return canonicalIssuer
}

import { useQuery, useQueryClient } from '@tanstack/react-query'

import { toLatestByIsin } from '@/domains/portfolio/features/holdings/features/positions/helpers/mappers/toLatestAllocationByIsin'
import type { IsinAllocation } from '@/domains/portfolio/features/holdings/features/positions/types/isinAllocation.type'
import { PORTFOLIO_ALLOCATION_QUERY_OPTIONS } from '@/domains/portfolio/shared/apis/queries/portfolioSourceQueries/portfolioAllocationQueryOptions'
import { portfolioQueryKeys } from '@/domains/portfolio/shared/apis/queryKeys'

export function useGetAllocationsByIsinQuery() {
  const queryClient = useQueryClient()
  return useQuery<Map<string, IsinAllocation>>({
    queryKey: portfolioQueryKeys.data('allocation-by-isin'),
    placeholderData: EMPTY_ISIN_ALLOCATIONS,
    // eslint-disable-next-line complexity -- reviewed: 2026-10-27; The four optional allocation dimensions use one explicit name-precedence and missing-point policy.
    queryFn: async () => {
      const { geo, secteur, currency, classe } = await queryClient.query({
        ...PORTFOLIO_ALLOCATION_QUERY_OPTIONS,
        staleTime: 'static',
      })
      const geoMap = toLatestByIsin(geo)
      const secteurMap = toLatestByIsin(secteur)
      const currencyMap = toLatestByIsin(currency)
      const classeMap = toLatestByIsin(classe)

      const allIsins = new Set([
        ...geoMap.keys(),
        ...secteurMap.keys(),
        ...currencyMap.keys(),
        ...classeMap.keys(),
      ])
      const data = new Map<string, IsinAllocation>()
      for (const isin of allIsins) {
        const name =
          geoMap.get(isin)?.name ??
          secteurMap.get(isin)?.name ??
          currencyMap.get(isin)?.name ??
          classeMap.get(isin)?.name ??
          isin
        data.set(isin, {
          isin,
          name,
          geo: geoMap.get(isin)?.point ?? null,
          secteur: secteurMap.get(isin)?.point ?? null,
          currency: currencyMap.get(isin)?.point ?? null,
          classe: classeMap.get(isin)?.point ?? null,
        })
      }
      return data
    },
  })
}

const EMPTY_ISIN_ALLOCATIONS = new Map<string, IsinAllocation>()

import { useMemo } from 'react'

import { useGetPositionHistoryQuery } from '@/domains/portfolio/features/holdings/features/positions/apis/queries/useGetPositionHistoryQuery'
import { buildSavingsHistorySeries } from '@/domains/portfolio/features/holdings/features/positions/components/PositionHoverDetails/helpers/calculators/buildHoverChartData/buildSavingsHistorySeries'
