import { useState } from 'react'

import type { OverviewConcentrationComparison } from '@/domains/portfolio/features/overview/helpers/calculators/buildOverviewComparison/buildOverviewComparison.types'
import { OverviewConcentrationRow } from '@/domains/portfolio/features/overview/pages/overviewChartDetails/OverviewConcentrationRow.view'
import { ConcentrationModeToggle } from '@/domains/portfolio/shared/components/ConcentrationModeToggle.view'
import { ScopedInfoTooltip } from '@/domains/portfolio/shared/components/kpis/ScopedInfoTooltip.feature'
import type { ConcentrationMode } from '@/domains/portfolio/shared/types/concentrationMode.type'
import i18n from '@/i18n/i18n'
import { Inline } from '@/shared/ui/layout/Inline.view'
import { Layout } from '@/shared/ui/layout/Layout.view'
import { Stack } from '@/shared/ui/layout/Stack.view'
import { Surface } from '@/shared/ui/Surface.view'
import { ToneSwatch } from '@/shared/ui/swatch/ToneSwatch.view'
import { Text } from '@/shared/ui/Text.view'

import { buildOverviewConcentrationRows } from './helpers/presenters/buildOverviewConcentrationRows'

export function OverviewConcentrationChart({
  heldConcentration,
  underlyingConcentration,
}: {
  heldConcentration: OverviewConcentrationComparison
  underlyingConcentration: OverviewConcentrationComparison
}) {
  const [mode, setMode] = useState<ConcentrationMode>('lookThrough')
  const lookThroughDisabled = underlyingConcentration.current == null
  const displayedMode =
    mode === 'lookThrough' && lookThroughDisabled ? 'held' : mode
  const concentration =
    displayedMode === 'held' ? heldConcentration : underlyingConcentration
  const { rows, scaleMax, previousAvailable } =
    buildOverviewConcentrationRows(concentration)

  const description =
    displayedMode === 'lookThrough'
      ? i18n.t(
          'ui.overviewcharts.directAndFundLookThroughExposureAvoidingWrapperLevel',
        )
      : i18n.t(
          'ui.overviewcharts.productsAndInstrumentsAsHeldIncludingPortfolioWrappers',
        )

  return (
    <Surface as="section" variant="panel">
      <Stack gap="default" align="start" justify="between">
        <div>
          <Text as="h3" variant="bodyStrong" tone="secondary">
            <Inline as="span" align="center">
              {displayedMode === 'lookThrough'
                ? i18n.t('ui.overviewcharts.largestUnderlyingAssets')
                : i18n.t('ui.overviewcharts.largestHeldPositions')}
              <ScopedInfoTooltip
                // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This chart chooses held versus underlying explanatory copy; ScopedInfoTooltip only renders it with live filter badges.
                text={description}
                // eslint-disable-next-line local/no-prop-drilling -- reviewed: 2026-10-27; This chart selects the concentration snapshot; ScopedInfoTooltip only adds live filter badges to the supplied reporting date.
                scope={{
                  account: 'filterable',
                  period: 'as-of',
                  effectiveDate: concentration.current?.date,
                }}
              />
            </Inline>
          </Text>
          <Layout spaceBefore="compact">
            <Text as="p" variant="caption" tone="subtle">
              {description}
            </Text>
          </Layout>
        </div>
        <ConcentrationModeToggle
          value={displayedMode}
          onChange={setMode}
          lookThroughDisabled={lookThroughDisabled}
        />
      </Stack>
      {rows.length === 0 ? (
        <Layout height="chart">
          <Text as="div" variant="body" tone="subtle" align="center">
            <Inline as="div" align="center" justify="center">
              {i18n.t(
                'ui.overviewcharts.historicalConcentrationIsUnavailableForThisPeriod',
              )}
            </Inline>
          </Text>
        </Layout>
      ) : (
        <Stack spaceBefore="spacious" gap="relaxed">
          {rows.map((row) => (
            <OverviewConcentrationRow
              key={row.key}
              previousAvailable={previousAvailable}
              row={row}
              scaleMax={scaleMax}
            />
          ))}
          <Text as="div" variant="tiny" tone="subtle">
            <Inline
              as="div"
              align="center"
              justify="end"
              gap="compact"
              inset="compact"
            >
              <Layout as="span" flow="inline" height="marker" width="divider">
                <ToneSwatch tone="secondary" />
              </Layout>{' '}
              {i18n.t('ui.overviewcharts.previousPeriodEnd')}
            </Inline>
          </Text>
        </Stack>
      )}
    </Surface>
  )
}

import type { TopPerformer } from '@/domains/portfolio/features/performance/helpers/calculators/performanceCalculations/performanceCalculations.types'
import { PORTFOLIO_CHART_TONES } from '@/domains/portfolio/shared/constants/portfolioChartTones'
import i18n from '@/i18n/i18n'
import { useFormatMoney } from '@/shared/helpers/formatters/useFormatMoney'
import { useFormatPercentage } from '@/shared/helpers/formatters/useFormatPercentage'
import { ChartText } from '@/shared/ui/ChartText.view'
import { type NumericTooltipProps } from '@/shared/ui/chartTooltip'
import { Layout } from '@/shared/ui/layout/Layout.view'
import { TooltipBox } from '@/shared/ui/TooltipBox.view'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; Optional name, account and amount metadata all describe one Recharts performer point.
export function TopPerformersTooltip({
  active,
  payload,
  label,
}: NumericTooltipProps<TopPerformer>) {
  const formatMoney = useFormatMoney()
  const formatPercentage = useFormatPercentage()
  if (payload == null) return null
  if (!active || payload.length === 0) return null
  const entry = payload[0]?.payload
  return (
    <TooltipBox>
      <Layout as="div" spaceAfter="compact">
        <ChartText as="div" tone={'tooltipText'} variant="strong">
          {entry?.name ?? label}
        </ChartText>
      </Layout>
      <Layout as="div" spaceAfter="compact">
        <ChartText as="div" tone={'tooltipDim'} variant="micro">
          {entry?.account_type}
        </ChartText>
      </Layout>
      <Layout as="div" spaceAfter="compact">
        <ChartText as="div" tone={'tooltipLabel'}>
          {i18n.t('ui.portfoliochartsTooltips.valueWithValues', {
            amount: formatMoney(entry?.value, { style: 'full', fallback: 0 }),
          })}
        </ChartText>
      </Layout>
      <ChartText
        as="div"
        tone={
          (entry?.pct ?? 0) >= 0
            ? PORTFOLIO_CHART_TONES.performancePositiveText
            : PORTFOLIO_CHART_TONES.performanceNegativeText
        }
        variant="strong"
      >
        {i18n.t('ui.portfoliochartsTooltips.unrealizedWithValues', {
          amount: formatMoney(entry?.gain, { style: 'full', fallback: 0 }),
          percentage: formatPercentage(entry?.pct, {
            signed: true,
            fallback: 0,
          }),
        })}
      </ChartText>
    </TooltipBox>
  )
}

import type { TriChartPoint } from '@/domains/portfolio/features/performance/helpers/calculators/performanceCalculations/performanceCalculations.types'
import { PORTFOLIO_CHART_TONES } from '@/domains/portfolio/shared/constants/portfolioChartTones'
import i18n from '@/i18n/i18n'
import { useFormatDate } from '@/shared/helpers/formatters/useFormatDate'
import { useFormatPercentage } from '@/shared/helpers/formatters/useFormatPercentage'
import { ChartText } from '@/shared/ui/ChartText.view'
import { type NumericTooltipProps } from '@/shared/ui/chartTooltip'
import { Layout } from '@/shared/ui/layout/Layout.view'
import { TooltipBox } from '@/shared/ui/TooltipBox.view'

// eslint-disable-next-line complexity -- reviewed: 2026-10-27; Observed and backfilled one-year and three-year series share one tooltip availability contract.
export function TriTooltip({
  active,
  payload,
  label,
}: NumericTooltipProps<TriChartPoint, Date | string | number>) {
  const formatDate = useFormatDate()
  const formatPercentage = useFormatPercentage()
  if (payload == null) return null
  if (!active || payload.length === 0) return null
  const tri1y =
    payload.find((point) => point.dataKey === 'tri_rolling_1y')?.value ?? null
  const tri1yBackfill =
    payload.find((point) => point.dataKey === 'tri_rolling_1y_backfill')
      ?.value ?? null
  const tri3y =
    payload.find((point) => point.dataKey === 'tri_rolling_3y')?.value ?? null
  const tri3yBackfill =
    payload.find((point) => point.dataKey === 'tri_rolling_3y_backfill')
      ?.value ?? null
  const showTri1y = tri1y !== null || tri1yBackfill !== null
  const showTri3y = tri3y !== null || tri3yBackfill !== null
  return (
    <TooltipBox>
      <Layout as="div" spaceAfter="compact">
        <ChartText as="div" tone={'tooltipText'}>
          {formatDate(label, { style: 'longMonthYear', fallback: '' })}
        </ChartText>
      </Layout>
      {showTri1y && (
        <ChartText
          as="div"
          tone={PORTFOLIO_CHART_TONES.totalChange}
          variant="strong"
        >
          {i18n.t('ui.portfoliochartsTooltips.irr1yWithValues', {
            value: formatPercentage(tri1y, {
              decimals: 2,
              signed: true,
              fallback: i18n.t('ui.portfoliochartsTooltips.notYetAvailable'),
            }),
          })}
        </ChartText>
      )}
      {showTri3y && (
        <Layout as="div" spaceBefore="compact">
          <ChartText
            as="div"
            tone={PORTFOLIO_CHART_TONES.returnRate}
            variant="strong"
          >
            {i18n.t('ui.portfoliochartsTooltips.irr3yWithValues', {
              value: formatPercentage(tri3y, {
                decimals: 2,
                signed: true,
                fallback: i18n.t('ui.portfoliochartsTooltips.notYetAvailable'),
              }),
            })}
          </ChartText>
        </Layout>
      )}
    </TooltipBox>
  )
}

import { IrrList } from '@/domains/portfolio/features/performance/components/PerformanceRankingLists/performanceRankingLists/IrrList.view'
import { useFormatExactPerformanceDateRange } from '@/domains/portfolio/features/performance/helpers/formatters/useFormatExactPerformanceDateRange'
import { buildAssetIrrRankings } from '@/domains/portfolio/features/performance/helpers/mappers/buildPerformanceContributionViewModel/buildAssetIrrRankings'
