                </Inline>
              </ChoiceRow>
            </Surface>
          </Layout>
          {accountGroups.map((group) => (
            <SelectAccountType
              key={group.type}
              accountLabels={accountLabels}
              accounts={group.accounts}
              onChange={onChange}
              selected={selected}
              type={group.type}
            />
          ))}
        </Inset>
      </Popover.Content>
    </Popover>
  )
}

