import { mapAnnualIncomeSavings } from '@/domains/portfolio/features/wealth/helpers/mappers/mapAnnualIncomeSavings/mapAnnualIncomeSavings'
import type { AnnualIncomeSavingsPoint } from '@/domains/portfolio/features/wealth/types/annualIncomeSavingsPoint.type'

function point(
  overrides: Partial<AnnualIncomeSavingsPoint>,
): AnnualIncomeSavingsPoint {
  return {
    year: 2024,
    incomeStatus: 'actual',
    netSalary: 50000,
    otherIncome: 10000,
    totalIncome: 60000,
    grossSalary: 75000,
    placedSavings: 30000,
    savingsThrough: new Date('2024-12-31'),
    savingsStatus: 'complete',
    placementRate: 50,
    unplacedIncomeProxy: 30000,
    comparable: true,
    ...overrides,
  }
}

describe('mapAnnualIncomeSavings', () => {
  it('maps nullable values, statuses and booleans', () => {
    const result = mapAnnualIncomeSavings([
      {
        year: 2026,
        income_status: 'forecast',
        net_salary: 60000,
        other_income: 12000,
        total_income: 72000,
        gross_salary: 90000,
        placed_savings: 10000,
        savings_through: new Date('2026-10-17'),
        savings_status: 'partial',
        placement_rate: null,
        unplaced_income_proxy: null,
        comparable: false,
      },
    ])

    expect(result).toEqual([
      point({
        year: 2026,
        incomeStatus: 'forecast',
        netSalary: 60000,
        otherIncome: 12000,
        totalIncome: 72000,
        grossSalary: 90000,
        placedSavings: 10000,
        savingsThrough: new Date('2026-10-17'),
        savingsStatus: 'partial',
        placementRate: null,
        unplacedIncomeProxy: null,
        comparable: false,
      }),
    ])
  })
})

describe('analyseIncomePlacement', () => {
  it('excludes forecast and non-comparable years from the relationship', () => {
    const result = analyseIncomePlacement([
      point({ year: 2023, totalIncome: 50000, placementRate: 40 }),
      point({ year: 2024, totalIncome: 60000, placementRate: 50 }),
      point({ year: 2025, comparable: false, placementRate: null }),
      point({
        year: 2026,
        incomeStatus: 'forecast',
        comparable: true,
        placementRate: 60,
      }),
    ])

    expect(result.points.map(({ year }) => year)).toEqual([2023, 2024])
    expect(result.correlation).toBeCloseTo(1)
    expect(result.slopePerTenThousand).toBeCloseTo(10)
    expect(result.trendLine).toEqual([
      { totalIncome: 50000, placementRate: 40 },
      { totalIncome: 60000, placementRate: 50 },
    ])
  })

  it('returns no statistic with insufficient or constant data', () => {
    expect(analyseIncomePlacement([point({})])).toMatchObject({
      correlation: null,
      slopePerTenThousand: null,
      trendLine: [],
    })
    expect(
      analyseIncomePlacement([
        point({ year: 2023, totalIncome: 60000, placementRate: 40 }),
        point({ year: 2024, totalIncome: 60000, placementRate: 50 }),
      ]),
    ).toMatchObject({
      correlation: null,
      slopePerTenThousand: null,
      trendLine: [],
    })
  })

  it('computes a negative relationship when placement rate falls with income', () => {
    const result = analyseIncomePlacement([
      point({ year: 2022, totalIncome: 40000, placementRate: 60 }),
      point({ year: 2023, totalIncome: 50000, placementRate: 50 }),
      point({ year: 2024, totalIncome: 60000, placementRate: 40 }),
    ])

    expect(result.correlation).toBeCloseTo(-1)
    expect(result.slopePerTenThousand).toBeCloseTo(-10)
  })
})

describe('filterAnnualIncomeSavingsByPeriod', () => {
  it('keeps calendar years intersecting the selected period', () => {
    const points = [
      point({ year: 2023 }),
      point({ year: 2024 }),
      point({ year: 2025 }),
    ]
    expect(
      filterAnnualIncomeSavingsByPeriod(
        points,
        new Date('2024-03-01'),
        new Date('2025-02-01'),
      ).map(({ year }) => year),
    ).toEqual([2024, 2025])
  })
})

import { useMemo } from 'react'

import { buildAccountTypeBreakdown } from '@/domains/portfolio/features/wealth/helpers/aggregators/buildAccountTypeBreakdown'
import { buildCumulativeWealthDrivers } from '@/domains/portfolio/features/wealth/helpers/calculators/wealthCalculations/buildCumulativeWealthDrivers'
import { computeTrailing12mSavings } from '@/domains/portfolio/features/wealth/helpers/calculators/wealthCalculations/computeTrailing12mSavings'
import { computeTrailing12mYearOverYear } from '@/domains/portfolio/features/wealth/helpers/calculators/wealthCalculations/computeTrailing12mYearOverYear'
import { filterMonthlyOpsByAccounts } from '@/domains/portfolio/features/wealth/helpers/selectors/filterMonthlyOpsByAccounts'
import { filterAnnualIncomeSavingsByPeriod } from '@/domains/portfolio/features/wealth/helpers/selectors/filterAnnualIncomeSavingsByPeriod'
import type { AnnualIncomeSavingsPoint } from '@/domains/portfolio/features/wealth/types/annualIncomeSavingsPoint.type'
import { useAccountTypeHistory } from '@/domains/portfolio/features/wealth/services/useAccountTypeHistory'
import type { MonthlyOperationsByMonth } from '@/domains/portfolio/features/wealth/types/monthlyOperation.type'
import { filterPointsByPeriod } from '@/domains/portfolio/shared/helpers/filters/filterPointsByPeriod'
import type { DashboardFilters } from '@/domains/portfolio/shared/types/dashboardFilters.type'
import type { PositionRow } from '@/domains/portfolio/shared/types/positionRow.type'
import type { SavingCapacityPoint } from '@/domains/portfolio/shared/types/savingCapacityPoint.type'

export function useDashboardWealth({
  savingCapacity,
  allMonthlyOps,
  annualIncomeSavings,
  currentPositions,
  filters,
}: DashboardWealthInput) {
  const periodSavings = useMemo(
    () =>
      filterPointsByPeriod(savingCapacity, filters.dateFrom, filters.dateTo),
    [filters.dateFrom, filters.dateTo, savingCapacity],
  )
  const trailingSavings = useMemo(
    () =>
      computeTrailing12mSavings(
        savingCapacity,
        filters.dateFrom,
        filters.dateTo,
      ),
    [filters.dateFrom, filters.dateTo, savingCapacity],
  )
  const trailingYearComparison = useMemo(
    () => computeTrailing12mYearOverYear(savingCapacity, filters.dateTo),
    [filters.dateTo, savingCapacity],
  )
  const wealthDrivers = useMemo(
    () => buildCumulativeWealthDrivers(periodSavings),
    [periodSavings],
  )
  const monthlyOps = useMemo(
    () => filterMonthlyOpsByAccounts(allMonthlyOps, filters.accounts),
    [allMonthlyOps, filters.accounts],
  )
  const typeHistory = useAccountTypeHistory(filters.accounts)
  const displayedTypeHistory = useMemo(
    () =>
      filterPointsByPeriod(typeHistory.data, filters.dateFrom, filters.dateTo),
    [filters.dateFrom, filters.dateTo, typeHistory.data],
  )
  const accountTypeData = useMemo(
    () => buildAccountTypeBreakdown(currentPositions),
    [currentPositions],
  )
  const displayedAnnualIncomeSavings = useMemo(
    () =>
      filterAnnualIncomeSavingsByPeriod(
        annualIncomeSavings,
        filters.dateFrom,
        filters.dateTo,
      ),
    [annualIncomeSavings, filters.dateFrom, filters.dateTo],
  )

  return useMemo(
    () => ({
      accountTypeData,
      displayedAnnualIncomeSavings,
      displayedTypeHistory,
      monthlyOps,
      trailingSavings,
      trailingYearComparison,
      typeHistory,
      wealthDrivers,
    }),
    [
      accountTypeData,
      displayedAnnualIncomeSavings,
      displayedTypeHistory,
      monthlyOps,
      trailingSavings,
      trailingYearComparison,
      typeHistory,
      wealthDrivers,
    ],
  )
}

type DashboardWealthInput = {
  savingCapacity: SavingCapacityPoint[]
  allMonthlyOps: MonthlyOperationsByMonth
  annualIncomeSavings: AnnualIncomeSavingsPoint[]
  currentPositions: PositionRow[]
  filters: DashboardFilters
}

